+                    node,
+                    mem.getTotal(),
+                    mem.getAdjustedTotal(),
+                    mlMax,
+                    mlNativeCodeOverhead,
+                    mlAnomalyDetectors,
+                    mlDataFrameAnalytics,
+                    mlNativeInference,
+                    jvmHeapMax,
+                    jvmInferenceMax,
+                    jvmInference
