+              text:
+                type: text
+                store: true
+
+  - do:
+      bulk:
+        index: test
+        refresh: true
+        body:
+          - '{ "index": {} }'
+          - '{ "page": 1, "text": "the quick brown fox" }'
+          - '{ "index": {} }'
+          - '{ "page": 1, "text": "jumped over the lazy dog" }'
+          - '{ "index": {} }'
+          - '{ "page": 2, "text": "The vorpal blade went snicker-snack!" }'
